/* eslint-disable @next/next/no-img-element -- a static SVG; next/image adds nothing on a static export. */

/** The Gleefy mark: the grinning party face from the app icon (public/logo.svg, generated by scripts/brand-icons.mjs). */
export function Logo({ size = 32 }: { size?: number }) {
  return (
    <img
      src="/logo.svg"
      alt=""
      aria-hidden="true"
      width={Math.round((size * 730) / 980)}
      height={size}
      decoding="async"
    />
  );
}
